package com.healthcare.portal.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime;
@Entity @Table(name="lab_orders") public class LabOrder { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="patient_id",nullable=false) private User patient; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="doctor_id") private DoctorProfile doctor; @Column(nullable=false,length=160) private String testName; @Column(length=30) private String status="ORDERED"; @Column(precision=12,scale=2) private BigDecimal amount=BigDecimal.ZERO; @Column(length=500) private String reportUrl; private LocalDateTime createdAt; @PrePersist void c(){createdAt=LocalDateTime.now();} public LabOrder(){} public LabOrder(User p,DoctorProfile d,String n,BigDecimal a){patient=p;doctor=d;testName=n;amount=a;} public Long getId(){return id;} public User getPatient(){return patient;} public DoctorProfile getDoctor(){return doctor;} public String getTestName(){return testName;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public BigDecimal getAmount(){return amount;} public String getReportUrl(){return reportUrl;} public void setReportUrl(String v){reportUrl=v;} public LocalDateTime getCreatedAt(){return createdAt;} }
